parameters.jsCode:
// One sheet row per business. Column names are what you'll see in the sheet.
const settings = $('Set your search').first().json;
const rows = [];
for (const item of $input.all()) {
  const b = item.json;
  if (settings.onlyBusinessesWithEmail && !b.email) continue;
  rows.push({
    json: {
      'Place ID': b.placeId,
      'Name': b.name,
      'Category': b.category ?? '',
      'Email': b.email ?? '',
      'Other emails': (b.emails ?? []).filter((e) => e !== b.email).join(', '),
      'Phone': b.phoneE164 ?? b.phone ?? '',
      'Website': b.website ?? '',
      'Address': b.address ?? '',
      'Rating': b.rating ?? '',
      'Reviews': b.reviewCount ?? '',
      'Instagram': b.instagram ?? '',
      'Facebook': b.facebook ?? '',
      'LinkedIn': b.linkedin ?? '',
      'Contact form': b.contactFormUrl ?? '',
      'Contacts status': b.contactsStatus ?? '',
      'Google Maps': b.googleMapsUrl ?? '',
      'Search': b.query ?? '',
      'Found on': (b.retrievedAt ?? '').slice(0, 10),
    },
  });
}
return rows;
